/**
 * Scoped per testing.md: this component's own contract (given props, does it render the right
 * branch and wire the right handler) — not ZimmSlideIndicator's own segment/clamp logic, which
 * is proven in its own index.test.tsx and rendered here for real (it is a lightweight,
 * side-effect-free presentational atom, so composing it directly costs nothing and gives real
 * integration confidence that this component passes it the right `count`/`activeIndex`).
 */
import React from 'react';
import { describe, test, expect, vi } from 'vitest';
import { render, screen, fireEvent } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { IntlProvider } from 'react-intl';
import { ZimmProductCardMedia } from './index';
import type { ZimmProductCardMediaImage } from './index';
import { ZimmProductCardMedia as ZimmProductCardMediaRecipe } from './zimmProductCardMedia.css';
import { CARD_SLOT, HOVER_CAPABLE_QUERY } from '../../zimmProductCardShared';

// Flat parts object covering both this component's own recipe AND ZimmSlideIndicator's
// (root/dot) — the same mocked useMultiStyleConfig is shared by both since neither test setup
// nor Chakra itself cares which recipe name asked for it. Same precedent as
// zimmSizeChipGroup/index.test.tsx's comment on its composed atom's unresolved styles.chip.
vi.mock('@chakra-ui/react', async (importOriginal) => {
  const actual = await importOriginal<typeof import('@chakra-ui/react')>();
  return {
    ...actual,
    useMultiStyleConfig: () => ({
      root: {},
      scrollContainer: {},
      slide: {},
      image: {},
      hoverSwapBase: {},
      hoverSwapOverlay: {},
      badge: {},
      badgeLabel: {},
      close: {},
      carousel: {},
      arrowButton: {},
      indicatorWrapper: {},
      dot: {},
    }),
  };
});

// ChevronLeftIcon / ChevronRightIcon / CloseIcon: the icons barrel has the Vitest SVG
// side-effect issue documented in .claude/rules/testing.md's "Known gap: ZimmIcon throws under
// Vitest" section. Mocked at the same relative specifier this component imports them from.
vi.mock('../../../icons', () => ({
  ChevronLeftIcon: () => null,
  ChevronRightIcon: () => null,
  CloseIcon: () => null,
}));

const wrap = (ui: React.ReactElement) =>
  render(
    <IntlProvider locale="en" defaultLocale="en">
      {ui}
    </IntlProvider>,
  );

const PRIMARY: ZimmProductCardMediaImage = { src: 'primary.jpg', alt: 'Zimmermann dress, front' };
const HOVER: ZimmProductCardMediaImage = { src: 'hover.jpg', alt: 'Zimmermann dress, on model' };
const GALLERY: ZimmProductCardMediaImage[] = [
  { src: 'g1.jpg', alt: 'Zimmermann dress, front' },
  { src: 'g2.jpg', alt: 'Zimmermann dress, side' },
  { src: 'g3.jpg', alt: 'Zimmermann dress, back' },
];

/** Mocks the scroll container's native `scrollTo` (absent under jsdom — see index.tsx's own
 *  comment) so an arrow click can be asserted against a spy instead of throwing. */
const mockScrollTo = (): ReturnType<typeof vi.fn> => {
  // HTMLElement already types `scrollTo` (lib.dom.d.ts) — jsdom just doesn't implement it at
  // runtime, so a plain mock-function assignment is enough; no cast needed.
  const scrollContainer = screen.getByTestId('card-media-scroll');
  const scrollTo = vi.fn();
  scrollContainer.scrollTo = scrollTo;
  return scrollTo;
};

describe('ZimmProductCardMedia — AC1: primary image renders with minimal props', () => {
  test('renders the primary image when hoverImage, images and showControls are all absent/false', () => {
    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} swapOnHover={false} showControls={false} />);
    const img = screen.getByRole('img', { name: PRIMARY.alt });
    expect(img).toHaveAttribute('src', PRIMARY.src);
  });
});

describe('ZimmProductCardMedia — alt text', () => {
  test('every rendered gallery image carries its own meaningful alt text', () => {
    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} images={GALLERY} swapOnHover={false} showControls />);
    GALLERY.forEach((image) => {
      expect(screen.getByRole('img', { name: image.alt })).toBeInTheDocument();
    });
  });

  test('a hover-swap pair keeps both images accessible by their own alt text', () => {
    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} hoverImage={HOVER} swapOnHover showControls={false} />);
    expect(screen.getByRole('img', { name: PRIMARY.alt })).toBeInTheDocument();
    expect(screen.getByRole('img', { name: HOVER.alt })).toBeInTheDocument();
  });
});

describe('ZimmProductCardMedia — lazy/eager loading', () => {
  test('the primary image lazy-loads by default (priority absent)', () => {
    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} swapOnHover={false} showControls={false} />);
    const img = screen.getByRole('img', { name: PRIMARY.alt });
    expect(img).toHaveAttribute('loading', 'lazy');
    expect(img).toHaveAttribute('decoding', 'async');
  });

  test('the primary image loads eagerly when priority is true', () => {
    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} swapOnHover={false} showControls={false} priority />);
    const img = screen.getByRole('img', { name: PRIMARY.alt });
    expect(img).not.toHaveAttribute('loading');
    expect(img).toHaveAttribute('decoding', 'async');
  });

  test('non-primary gallery images are always lazy, even when priority is true', () => {
    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} images={GALLERY} swapOnHover={false} showControls priority />);
    expect(screen.getByRole('img', { name: GALLERY[0].alt })).not.toHaveAttribute('loading');
    expect(screen.getByRole('img', { name: GALLERY[1].alt })).toHaveAttribute('loading', 'lazy');
    expect(screen.getByRole('img', { name: GALLERY[2].alt })).toHaveAttribute('loading', 'lazy');
  });

  test('the hover-swap overlay image is always lazy, even when priority is true', () => {
    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} hoverImage={HOVER} swapOnHover showControls={false} priority />);
    expect(screen.getByRole('img', { name: PRIMARY.alt })).not.toHaveAttribute('loading');
    expect(screen.getByRole('img', { name: HOVER.alt })).toHaveAttribute('loading', 'lazy');
  });
});

describe('ZimmProductCardMedia — single image renders no paging affordance', () => {
  test('renders no arrow buttons and no slide indicator, even when showControls is true', () => {
    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} swapOnHover={false} showControls />);
    expect(screen.queryAllByRole('button')).toHaveLength(0);
    expect(screen.queryByRole('group')).not.toBeInTheDocument(); // ZimmSlideIndicator's role=group
  });

  test('a 1-entry images array behaves identically to an absent images array', () => {
    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} images={[GALLERY[0]]} swapOnHover={false} showControls />);
    expect(screen.queryAllByRole('button')).toHaveLength(0);
    expect(screen.queryByRole('group')).not.toBeInTheDocument();
  });
});

describe('ZimmProductCardMedia — arrows wrap at both ends', () => {
  test('Next from the last image wraps to the first, updates the indicator, and calls scrollTo with a plausible shape', async () => {
    const user = userEvent.setup();
    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} images={GALLERY} swapOnHover={false} showControls />);
    const scrollTo = mockScrollTo();

    const next = screen.getByRole('button', { name: 'Next image' });
    await user.click(next); // 0 -> 1
    await user.click(next); // 1 -> 2 (last)
    scrollTo.mockClear();
    await user.click(next); // wraps 2 -> 0

    expect(scrollTo).toHaveBeenCalledTimes(1);
    // jsdom reports clientWidth as 0 regardless of index, so the numeric offset itself cannot
    // prove which slide was requested — only that a plausible {left, behavior} shape was sent.
    expect(scrollTo).toHaveBeenCalledWith(expect.objectContaining({ left: expect.any(Number), behavior: 'smooth' }));
    // The logical wrap is proven via the composed (real, unmocked) slide indicator's accessible
    // name, which reflects `activeIndex` from pure component state regardless of jsdom layout.
    expect(screen.getByRole('group', { name: 'Image 1 of 3' })).toBeInTheDocument();
  });

  test('Previous from the first image wraps to the last, updates the indicator, and calls scrollTo with a plausible shape', async () => {
    const user = userEvent.setup();
    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} images={GALLERY} swapOnHover={false} showControls />);
    const scrollTo = mockScrollTo();

    const previous = screen.getByRole('button', { name: 'Previous image' });
    await user.click(previous); // wraps 0 -> 2 (last)

    expect(scrollTo).toHaveBeenCalledTimes(1);
    expect(scrollTo).toHaveBeenCalledWith(expect.objectContaining({ left: expect.any(Number), behavior: 'smooth' }));
    expect(screen.getByRole('group', { name: 'Image 3 of 3' })).toBeInTheDocument();
  });
});

describe('ZimmProductCardMedia — remove (close) overlay', () => {
  test('renders nothing when onRemove is absent', () => {
    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} swapOnHover={false} showControls={false} />);
    expect(document.querySelector(`[data-card-slot="${CARD_SLOT.close}"]`)).not.toBeInTheDocument();
  });

  test('renders nothing when onRemove is supplied without a usable removeLabel (defensive no-op)', () => {
    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} swapOnHover={false} showControls={false} onRemove={vi.fn()} />);
    expect(document.querySelector(`[data-card-slot="${CARD_SLOT.close}"]`)).not.toBeInTheDocument();
  });

  test('renders nothing when removeLabel is only whitespace', () => {
    wrap(
      <ZimmProductCardMedia
        primaryImage={PRIMARY}
        swapOnHover={false}
        showControls={false}
        onRemove={vi.fn()}
        removeLabel="   "
      />,
    );
    expect(document.querySelector(`[data-card-slot="${CARD_SLOT.close}"]`)).not.toBeInTheDocument();
  });

  test('renders a real, labelled button and calls onRemove on click when both are supplied', async () => {
    const onRemove = vi.fn();
    const user = userEvent.setup();
    wrap(
      <ZimmProductCardMedia
        primaryImage={PRIMARY}
        swapOnHover={false}
        showControls={false}
        onRemove={onRemove}
        removeLabel="Remove Zimmermann dress from wishlist"
      />,
    );
    const button = screen.getByRole('button', { name: 'Remove Zimmermann dress from wishlist' });
    expect(button.tagName).toBe('BUTTON');
    await user.click(button);
    expect(onRemove).toHaveBeenCalledTimes(1);
  });
});

describe('ZimmProductCardMedia — badge overlay', () => {
  test('renders nothing when badge is absent', () => {
    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} swapOnHover={false} showControls={false} />);
    expect(document.querySelector(`[data-card-slot="${CARD_SLOT.badge}"]`)).not.toBeInTheDocument();
  });

  test('renders nothing when badge is only whitespace (same guard shape as removeLabel)', () => {
    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} swapOnHover={false} showControls={false} badge="   " />);
    expect(document.querySelector(`[data-card-slot="${CARD_SLOT.badge}"]`)).not.toBeInTheDocument();
  });

  test('renders the label text when a real badge is supplied', () => {
    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} swapOnHover={false} showControls={false} badge="Runway" />);
    expect(document.querySelector(`[data-card-slot="${CARD_SLOT.badge}"]`)).toBeInTheDocument();
    expect(screen.getByText('Runway')).toBeInTheDocument();
  });
});

describe('ZimmProductCardMedia — hover-swap keeps both images in the DOM simultaneously', () => {
  test('primary and hover images are both present at once, not conditionally rendered', () => {
    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} hoverImage={HOVER} swapOnHover showControls={false} />);
    expect(screen.getAllByRole('img')).toHaveLength(2);
  });

  test('hover-swap does not activate without swapOnHover, even when hoverImage is supplied', () => {
    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} hoverImage={HOVER} swapOnHover={false} showControls={false} />);
    expect(screen.getAllByRole('img')).toHaveLength(1);
  });

  test('hover-swap does not activate once a >1 image gallery takes over', () => {
    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} hoverImage={HOVER} images={GALLERY} swapOnHover showControls />);
    // 3 gallery images, no extra hoverImage layer on top of the first.
    expect(screen.getAllByRole('img')).toHaveLength(3);
  });
});

describe('ZimmProductCardMedia — data-card-slot selector contract for the organism (Step 6)', () => {
  test('stamps every documented data-card-slot value when all optional slots are active', () => {
    wrap(
      <ZimmProductCardMedia
        primaryImage={PRIMARY}
        images={GALLERY}
        swapOnHover={false}
        showControls
        badge="Runway"
        onRemove={vi.fn()}
        removeLabel="Remove from wishlist"
      />,
    );
    expect(document.querySelector(`[data-card-slot="${CARD_SLOT.media}"]`)).toBeInTheDocument();
    expect(document.querySelector(`[data-card-slot="${CARD_SLOT.badge}"]`)).toBeInTheDocument();
    expect(document.querySelector(`[data-card-slot="${CARD_SLOT.close}"]`)).toBeInTheDocument();
    expect(document.querySelector(`[data-card-slot="${CARD_SLOT.carousel}"]`)).toBeInTheDocument();
    expect(document.querySelector(`[data-card-slot="${CARD_SLOT.indicator}"]`)).toBeInTheDocument();
  });
});

/**
 * Fix 1 (Scorer round 1, SFCC-236 Step 4 rework): the 19 tests above all render through the
 * `vi.mock('@chakra-ui/react', ...)` at the top of this file, which replaces useMultiStyleConfig
 * with a flat `{}` return for every part — none of them ever evaluate the REAL recipe object.
 * Proved live by the Scorer: deleting the recipe's HOVER_CAPABLE_QUERY media-query gate entirely
 * (making the desktop arrows permanently visible regardless of pointer capability) left the
 * whole suite green. These tests import the recipe module directly and call its exported
 * baseStyle(), bypassing the mock entirely — same technique as
 * zimmSizeChip.css.test.ts / zimmTextInput.css.test.ts.
 */
describe('ZimmProductCardMedia — real recipe assertions (bypasses the useMultiStyleConfig mock)', () => {
  test('carousel (arrows) and indicatorWrapper are mutually exclusive within the same media-query key', () => {
    const style = ZimmProductCardMediaRecipe.baseStyle();

    // Touch / non-hover-capable pointers (outside the media query): indicator visible, arrows hidden.
    expect(style.indicatorWrapper.display).toBe('block');
    expect(style.carousel.display).toBe('none');

    // Hover-capable pointers (inside the SAME media-query key, on both parts): arrows visible,
    // indicator hidden. Bracket-indexed via a `Record<string, unknown>` cast, same precedent as
    // zimmTextInput.css.test.ts's `row as Record<string, unknown>` — a `@media` key is a real
    // CSSObject selector at runtime but isn't one of SystemStyleObject's named literal keys.
    const carousel = style.carousel as Record<string, unknown>;
    const indicatorWrapper = style.indicatorWrapper as Record<string, unknown>;
    const carouselHoverBlock = carousel[HOVER_CAPABLE_QUERY] as Record<string, unknown>;
    const indicatorHoverBlock = indicatorWrapper[HOVER_CAPABLE_QUERY] as Record<string, unknown>;

    expect(carouselHoverBlock.display).toBe('flex');
    expect(indicatorHoverBlock.display).toBe('none');

    // Explicit mutual-exclusivity: never the same visibility on both parts, in either
    // media-query state.
    expect(style.carousel.display).not.toBe(style.indicatorWrapper.display);
    expect(carouselHoverBlock.display).not.toBe(indicatorHoverBlock.display);
  });

  test("badge and close share the same fixed height, so their centred content lands on the same vertical line — regression guard: padding-only sizing on badge previously grew it to 64px against close's fixed 48px, landing badge text 9px below the close icon", () => {
    const style = ZimmProductCardMediaRecipe.baseStyle();
    expect(style.badge.height).toBe(style.close.height);
    expect(style.badge.display).toBe('flex');
    expect(style.badge.alignItems).toBe('center');
  });

  test('close and arrowButton both carry the standard keyboard focus-visible outline', () => {
